1	'use client';
2	
3	import {
4	    Anchor,
5	    Tooltip,
6	    useMantineTheme,
7	} from '@mantine/core';
8	import { IconArrowBigLeftLine, IconArrowBigRightLine } from '@tabler/icons-react';
9	import type { PlayerType } from 'prisma/zod/schemas/models/Player.schema';
10	import { CSSProperties } from 'react';
11	
12	/**
13	 * Component for rendering a link to a player's profile with various formatting options.
14	 *
15	 * @param player - The player data to link to
16	 * @param year - The year to include in the link URL (optional)
17	 * @param format - The format for the link label (default: 'name')
18	 *   - 'name': Displays the player's name as the link label
19	 *   - 'left-arrow': Displays a left arrow icon, indicating a link to the previous player
20	 *   - 'right-arrow': Displays a right arrow icon, indicating a link to the next player
21	 * @param wrap - Whether the player's name may wrap onto multiple lines (default: false,
22	 *   i.e. the link gets enough min-width to keep a typical name on one line)
23	 * @returns A React element representing the formatted player link
24	 * @example
25	 * <PlayerLink player={player} year={2024} format="name" />
26	 * // Renders a link with the player's name as the label, linking to "/footy/player/{player.id}/2024"
27	 * @example
28	 * <PlayerLink player={player} format="left-arrow" />
29	 * // Renders a link with a left arrow icon, linking to "/footy/player/{player.id}"
30	 * @example
31	 * <PlayerLink player={player} format="right-arrow" />
32	 * // Renders a link with a right arrow icon, linking to "/footy/player/{player.id}"
33	 */
34	export interface Props {
35	    player: PlayerType;
36	    year: number;
37	    format?: 'name' | 'left-arrow' | 'right-arrow';
38	    wrap?: boolean;
39	}
40	
41	export const PlayerLink = ({
42	    player,
43	    year,
44	    format = 'name',
45	    wrap = false,
46	}: Props) => {
47	    const theme = useMantineTheme();
48	    let ariaLabel: string | undefined;
49	    let miw: CSSProperties['minWidth'];
50	
51	    switch (format) {
52	        case 'name':
53	            ariaLabel = `${player.name ?? 'Unknown'}`;
54	            miw = wrap ?
55	                theme.other.playerNameMinWidthMultiLine :
56	                theme.other.playerNameMinWidthSingleLine;
57	            break;
58	        case 'left-arrow':
59	            ariaLabel = `Previous player: ${player.name ?? 'Unknown'}`;
60	            break;
61	        case 'right-arrow':
62	            ariaLabel = `Next player: ${player.name ?? 'Unknown'}`;
63	            break;
64	    }
65	
66	    const link = (
67	        <Anchor
68	            href={`/footy/player/${player.id}${year ? `/${year}` : ''}`}
69	            ta="center"
70	            aria-label={ariaLabel}
71	            miw={miw}
72	            bd="1px solid pink"
73	        >
74	            {(() => {
75	                switch (format) {
76	                    case 'name':
77	                        return player.name;
78	                    case 'left-arrow':
79	                        return <IconArrowBigLeftLine aria-hidden />;
80	                    case 'right-arrow':
81	                        return <IconArrowBigRightLine aria-hidden />;
82	                }
83	            })()}
84	        </Anchor>
85	    );
86	
87	    if (format === 'name') {
88	        return link;
89	    }
90	    else {
91	        return (
92	            <Tooltip label={player.name} withArrow>
93	                {link}
94	            </Tooltip>
95	        );
96	    }
97	};
