43	    // that's worth a skeleton for — they simply reveal together once the
44	    // mugshot (whose own AspectRatio already reserves the card's footprint)
45	    // has finished loading, rather than each popping in independently.
46	    const [mugshotReady, setMugshotReady] = useState(false);
47	    // Fading via opacity alone would still leave these hit-testable, exposed
48	    // to assistive tech, and keyboard-focusable while "hidden". `inert` is
49	    // the one attribute that covers all three (pointer, a11y tree, and
50	    // focus) for any content that ends up inside these overlays, now or
51	    // later; `pointerEvents`/`aria-hidden` stay on as a fallback for browsers
52	    // that don't yet support `inert`.
53	    const overlayStyle = {
54	        opacity: mugshotReady ? 1 : 0,
55	        pointerEvents: mugshotReady ? 'auto' : 'none',
56	        transition: 'opacity 150ms ease',
57	    } as const;
58	
59	    return (
60	        <Box w="100%" pos="relative" className={classes.imageContainer}>
61	            <PlayerMugshot player={player} onReady={() => setMugshotReady(true)} />
62	            <Box
63	                className={classes.trophies}
64	                left="0.5em"
65	                top="0.5em"
66	                style={overlayStyle}
67	                aria-hidden={!mugshotReady}
68	                inert={!mugshotReady}
69	            >
70	                <PlayerTrophies trophies={trophies} />
71	            </Box>
72	            <Box
73	                className={classes.badges}
74	                right="0.5em"
