import { chromium, devices } from 'playwright';

const iphone15 = devices['iPhone 15'];
const browser = await chromium.launch();
const context = await browser.newContext({ ...iphone15, deviceScaleFactor: 2 });
const page = await context.newPage();

await page.goto('http://localhost:3000/footy/game', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(2000);

for (let i = 0; i < 15; i++) {
    const noPlayersCount = await page.getByText('No players selected.').count();
    if (noPlayersCount === 0) break;
    await page.locator('a[href^="/footy/game/"]').first().click();
    await page.waitForTimeout(600);
}
await page.waitForTimeout(1000);

console.log('URL:', page.url());
console.log('Viewport width (base breakpoint check, xs=576px):', page.viewportSize().width);

await page.screenshot({ path: '/private/tmp/claude-501/-Volumes-Development-next-www-toastboy/a86654cd-940d-468b-8d0f-161de842c8aa/scratchpad/mobile-row.png' });

const row = page.locator('.mantine-Card-root').first();
const diag = await row.evaluate((el) => {
    const rect = (e) => { const r = e.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
    const cs = (e) => getComputedStyle(e);
    const sections = Array.from(el.children);
    return {
        root: { rect: rect(el), display: cs(el).display, alignItems: cs(el).alignItems, height: cs(el).height },
        sections: sections.map((s) => ({
            rect: rect(s),
            display: cs(s).display,
            height: cs(s).height,
            alignSelf: cs(s).alignSelf,
            flexShrink: cs(s).flexShrink,
            flexGrow: cs(s).flexGrow,
            flexBasis: cs(s).flexBasis,
            childOuterHTML: s.outerHTML.slice(0, 300),
        })),
    };
});
console.log('DIAG:', JSON.stringify(diag, null, 2));

await browser.close();

