const row = page.locator('.mantine-Card-root').first();
const diag = await row.evaluate((el) => {
    const rect = (e) => { const r = e.getBoundingClientRect(); return { x: Math.round(r.x), w: Math.round(r.width) }; };
    const cs = (e) => getComputedStyle(e);
    const sections = Array.from(el.children).filter((c) => c.tagName === 'DIV' && c.className.includes('Card-section'));
    return {
        root: rect(el),
        sections: sections.map((s) => ({
            rect: rect(s),
            flexGrow: cs(s).flexGrow,
            flexShrink: cs(s).flexShrink,
            flexBasis: cs(s).flexBasis,
        })),
    };
});
console.log('DIAG @440px:', JSON.stringify(diag, null, 2));

await browser.close();

